class Solution {
public:
    int minSwaps(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<int> maxRight(n, -1);

        for (int i = 0; i < n; i++) {
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    maxRight[i] = j;
                    break;
                }
            }
        }

        int swaps = 0;
        for (int i = 0; i < n; i++) {
            int found = -1;
            for (int j = i; j < n; j++) {
                if (maxRight[j] <= i) {
                    found = j;
                    break;
                }
            }
            if (found == -1) return -1;

            for (int j = found; j > i; j--) {
                swap(maxRight[j], maxRight[j - 1]);
                swaps++;
            }
        }

        return swaps;
    }
};
